var LIBS={'numpy':'NumPy: super-fast maths on whole lists (arrays) of numbers at once.','pandas':'Pandas: Excel inside Python. Load, clean, filter and summarise tables of data.','matplotlib':'Matplotlib: draws charts and graphs.','matplotlib.pyplot':'Matplotlib\'s plotting tools: bar charts, line charts, scatter plots.','seaborn':'Seaborn: good-looking statistical charts with less code.','sklearn':'scikit-learn: ready-made machine learning models and tools.','sklearn.model_selection':'scikit-learn helpers to split data and test models fairly (train/test split, cross-validation).','sklearn.linear_model':'scikit-learn\'s line-based models: linear and logistic regression.','sklearn.ensemble':'scikit-learn models made of many trees: random forest and gradient boosting.','sklearn.metrics':'scikit-learn scorecards: accuracy, precision, recall, error and similarity.','sklearn.preprocessing':'scikit-learn tools to prepare data: scaling numbers, encoding categories.','sklearn.cluster':'scikit-learn tools that group similar rows automatically (k-means, DBSCAN).','sklearn.decomposition':'scikit-learn tools to squeeze many columns into a few (PCA).','sklearn.feature_extraction.text':'scikit-learn tools that turn text into numbers (TF-IDF, word counts).','sklearn.pipeline':'scikit-learn pipelines: chain preparation steps and a model into one object.','sklearn.datasets':'Practice datasets that come with scikit-learn.','sklearn.tree':'scikit-learn decision trees: yes/no questions that lead to an answer.','sklearn.neighbors':'scikit-learn k-nearest neighbours: decide by looking at the most similar examples.','sklearn.svm':'scikit-learn support vector machines.','sklearn.naive_bayes':'scikit-learn Naive Bayes: fast probability-based classifiers.','sklearn.impute':'scikit-learn tools to fill in missing values.','sklearn.compose':'scikit-learn tools to treat different columns differently.','sklearn.inspection':'scikit-learn tools to see which features a model relies on.','scipy':'SciPy: advanced maths and statistics.','json':'json: read and write JSON, the text format apps and APIs use to share data.','re':'re: regular expressions, patterns for finding text (like all phone numbers).','math':'math: square roots, logs, rounding and other maths.','random':'random: random numbers and shuffling.','os':'os: talk to the operating system: files, folders, environment variables.','sys':'sys: settings of the running Python program.','time':'time: clocks and waiting.','datetime':'datetime: dates and times.','collections':'collections: handy containers like Counter (counting) and defaultdict.','itertools':'itertools: tools for looping in clever ways.','functools':'functools: tools that work on functions.','pathlib':'pathlib: work with file and folder paths safely.','csv':'csv: read and write CSV spreadsheet files.','sqlite3':'sqlite3: a small SQL database built into Python.','hashlib':'hashlib: makes fingerprints (hashes) of data.','subprocess':'subprocess: run other programs from Python.','tempfile':'tempfile: temporary files and folders that are cleaned up later.','shutil':'shutil: copy, move and delete files and folders.','difflib':'difflib: compare two texts and show the differences.','ast':'ast: read Python code as a tree (used here to do maths safely).','operator':'operator: +, -, *, / as functions.','inspect':'inspect: look inside functions (names, inputs, docstrings).','typing':'typing: labels that say what type of data a variable holds.','dataclasses':'dataclasses: quick classes for holding data.','concurrent.futures':'concurrent.futures: run several jobs at the same time.','asyncio':'asyncio: do many waiting tasks (like API calls) at once.','contextlib':'contextlib: helpers for "with" blocks.','urllib.parse':'urllib.parse: split a web address (URL) into its parts.','graphlib':'graphlib: put tasks in the right order when some depend on others.','resource':'resource: limit how much CPU and memory a program may use.','requests':'requests: download web pages and call web APIs.','anthropic':'anthropic: the official Python library for calling Claude models.','openai':'openai: the official Python library for OpenAI models (also used by some other providers).','google':'Google\'s Python library, here for Gemini models.','langchain':'LangChain: building blocks for LLM apps (prompts, chains, retrievers).','langchain_core':'LangChain\'s core pieces: prompts, messages, output parsers, tools.','langchain_anthropic':'LangChain\'s connector for Claude models.','langchain_openai':'LangChain\'s connector for OpenAI models.','langchain_community':'Community connectors for LangChain: loaders, vector stores and more.','langchain_text_splitters':'LangChain tools that cut long text into chunks.','langgraph':'LangGraph: build AI agents as a map of steps (a graph).','llama_index':'LlamaIndex: tools to index your documents and ask questions over them.','crewai':'CrewAI: build teams of AI agents with roles and tasks.','mcp':'MCP: the official library for the Model Context Protocol (connect AI apps to tools).','chromadb':'Chroma: a vector database that stores embeddings and finds similar text.','transformers':'Hugging Face Transformers: download and run thousands of open AI models.','datasets':'Hugging Face Datasets: load training and test data.','peft':'PEFT: cheap fine-tuning methods like LoRA.','trl':'TRL: training helpers for fine-tuning language models.','torch':'PyTorch: a deep learning framework for building and training neural networks.','tensorflow':'TensorFlow: a deep learning framework from Google.','keras':'Keras: an easy way to build neural networks layer by layer.','cv2':'OpenCV: tools for images and video.','PIL':'Pillow: open, edit and save images.','streamlit':'Streamlit: turn a Python script into a web app.','fastapi':'FastAPI: build web APIs (URLs other programs can call).','pydantic':'Pydantic: checks that data has the right fields and types.','uvicorn':'Uvicorn: the web server that runs a FastAPI app.','joblib':'joblib: save a trained model to a file and load it later.','pyspark':'PySpark: process huge data across many computers.','pymongo':'PyMongo: talk to a MongoDB database.','statsmodels':'statsmodels: statistics and forecasting models.','nltk':'NLTK: classic tools for working with human language.','playwright':'Playwright: control a real web browser from code.','diffusers':'Diffusers: run image-generation (diffusion) models.','whisper':'Whisper: turn speech into text.','xgboost':'XGBoost: a powerful gradient boosting model.','dotenv':'python-dotenv: load secret keys from a .env file.','claude_agent_sdk':'Claude Agent SDK: build agents with the same loop and tools as Claude Code.','agents':'OpenAI Agents SDK: agents, tools and hand-offs.'};var METHODS=[[/\bnp\.array\(/,'makes a NumPy array: a fast list (or table) of numbers.'],[/\bpd\.DataFrame\(/,'makes a table (DataFrame) with rows and columns.'],[/\bpd\.Series\(/,'makes a single column of data (a Series).'],[/\banthropic\.Anthropic\(/,'creates a Claude client that reads your API key from the environment.'],[/\bsqlite3\.connect\(/,'opens (or creates) a SQLite database.'],[/\bplt\.(bar|plot|scatter|hist)\(/,'draws a chart.'],[/\bTfidfVectorizer\(/,'creates a tool that turns text into TF-IDF numbers.'],[/\bcosine_similarity\(/,'measures how similar two vectors are (1 = same direction).'],[/\btrain_test_split\(/,'splits the data into a training part (to learn from) and a test part (to check on).'],[/\.fit_transform\(/,'learns from the data and transforms it in one step.'],[/\.fit\(/,'trains (fits) the model on the data.'],[/\.predict_proba\(/,'asks the trained model for probabilities.'],[/\.predict\(/,'asks the trained model for its answers (predictions).'],[/\.transform\(/,'applies what was learned to change the data.'],[/\.score\(/,'measures how well the model does.'],[/\bread_csv\(/,'loads a CSV file into a table (DataFrame).'],[/\.groupby\(/,'groups rows that share a value, like all sales per city.'],[/\.describe\(/,'gives quick statistics: count, mean, min, max.'],[/\.head\(/,'shows the first few rows.'],[/\.messages\.create\(/,'sends a message to the AI model and waits for its reply.'],[/\.messages\.stream\(/,'asks the AI model and receives the reply word by word.'],[/\.invoke\(/,'runs the chain or graph and returns the result.'],[/\bjson\.loads\(/,'turns JSON text into a Python dictionary or list.'],[/\bjson\.dumps\(/,'turns Python data into JSON text.'],[/\.execute\(/,'runs an SQL command on the database.'],[/\.append\(/,'adds one item to the end of a list.'],[/\.split\(/,'cuts text into a list of pieces.'],[/\.join\(/,'glues a list of texts into one text.'],[/\.replace\(/,'swaps some text for other text.'],[/\.lower\(/,'makes text lowercase.'],[/\.strip\(/,'removes spaces from the start and end.'],[/\.items\(\)/,'goes through each key and value of a dictionary.'],[/\.get\(/,'reads a value from a dictionary safely (no error if it is missing).'],[/\bsorted\(/,'returns the items in order.'],[/\blen\(/,'counts how many items there are.'],[/\brange\(/,'makes a sequence of numbers.'],[/\bsum\(/,'adds up the numbers.'],[/\bround\(/,'rounds the number.'],[/\bmax\(/,'picks the biggest.'],[/\bmin\(/,'picks the smallest.'],[/\bopen\(/,'opens a file.'],[/\.compile\(/,'prepares the model or graph so it can run.'],[/\.show\(/,'shows the chart or table.']];function libInfo(name){var parts=name.split('.');for(var i=parts.length;i>0;i--){var key=parts.slice(0,i).join('.');if(LIBS[key])return LIBS[key];}
return'';}
function libSay(name){var i=libInfo(name),c=i.indexOf(':');return c>-1&&!/\s/.test(i.slice(0,c).trim().replace(/['’]s$/,''))?i.slice(c+1).trim():i.replace(/: /,', ').replace(/\.$/,'');}
function parseImports(code){var out=[];code.split('\n').forEach(function(ln){var m;if((m=ln.match(/^\s*from\s+([\w.]+)\s+import\s+(.+)$/))){out.push({mod:m[1],names:m[2].replace(/[()\\]/g,'').split(',').map(function(s){return s.trim().split(/\s+as\s+/)[0];}).filter(Boolean)});}else if((m=ln.match(/^\s*import\s+(.+)$/))){m[1].split(',').forEach(function(p){var bits=p.trim().split(/\s+as\s+/);out.push({mod:bits[0],alias:bits[1]||''});});}});return out;}
function describeValue(v){v=v.trim();if(/^\[/.test(v))return'a list (an ordered collection)';if(/^\{/.test(v))return/:/.test(v)||/^\{\s*$/.test(v)||v==='{}'?'a dictionary (labels → values)':'a set';if(/^\(/.test(v)&&/,/.test(v))return'a tuple (a fixed group of values)';if(/^(f|r|b)?["']/.test(v))return'text (a string)';if(/^-?\d+(_\d+)*$/.test(v))return'a whole number';if(/^-?\d*\.\d+(e-?\d+)?$/.test(v))return'a decimal number';if(/^(True|False)$/.test(v))return'True or False';if(/^None$/.test(v))return'nothing yet (None)';if(/^lambda\b/.test(v))return'a tiny one-line function';return'';}
